1	import { db } from '@/lib/db';
2	import { formatErrorForUser } from '@/lib/errors/format-error-for-user';
3	import {
4	  crmContacts,
5	  estimateEvents,
6	  estimateFees,
7	  estimateLineItems,
8	  estimates,
9	  hubInvoices,
10	  locations,
11	} from '@/lib/schema/index';
12	import { isUuid, verifyLocationAccess } from '@/server/helpers';
13	import {
14	  type AuthUser,
15	  requireAdmin,
16	  requireAuth,
17	} from '@/server/middleware/auth';
18	import { and, asc, desc, eq, ilike, isNull, lt, or, sql } from 'drizzle-orm';
19	import { Hono } from 'hono';
20	
21	export const estimatesRouter = new Hono<{
22	  Variables: { authUser?: AuthUser };
23	}>();
24	
25	// ─────────────────────────────────────────────────────────────────────────────
26	// Helpers
27	// ─────────────────────────────────────────────────────────────────────────────
28	
29	async function allocateEstimateNumber(locationId: string): Promise<string> {
30	  const [row] = await db
31	    .execute(
32	      sql`UPDATE ${locations}
33	          SET next_estimate_number = next_estimate_number + 1
34	          WHERE id = ${locationId}
35	          RETURNING next_estimate_number`,
36	    )
37	    .then((r) => r.rows as { next_estimate_number: number }[]);
38	  const n = row?.next_estimate_number ?? 1;
39	  return `EST-${String(n).padStart(4, '0')}`;
40	}
41	
42	async function logEvent(
43	  estimateId: string,
44	  eventType: string,
45	  actorType: string | null,
46	  actorId: string | null,
47	  payload?: Record<string, unknown>,
48	) {
49	  await db.insert(estimateEvents).values({
50	    estimateId,
51	    eventType,
52	    actorType,
53	    actorId,
54	    payload: payload ?? null,
55	  });
56	}
57	
58	// ─────────────────────────────────────────────────────────────────────────────
59	// GET /locations/:locationId/estimates — list with filters + pagination
60	// ─────────────────────────────────────────────────────────────────────────────
61	
62	estimatesRouter.get(
63	  '/locations/:locationId/estimates',
64	  requireAuth(),
65	  async (c) => {
66	    const { locationId } = c.req.param();
67	    if (!isUuid(locationId))
68	      return c.json({ error: 'Invalid location ID' }, 400);
69	
70	    const authUser = c.get('authUser') as AuthUser;
71	    const location = await verifyLocationAccess(locationId, authUser);
72	    if (!location)
73	      return c.json({ error: 'Location not found or access denied' }, 403);
74	
75	    const {
76	      status,
77	      search,
78	      contactId,
79	      dateFrom,
80	      dateTo,
81	      sortBy = 'created_at',
82	      sortDir = 'desc',
83	      page = '1',
84	      limit = '50',
85	    } = c.req.query();
86	
87	    const pageNum = Math.max(1, Number.parseInt(page, 10));
88	    const limitNum = Math.min(200, Math.max(1, Number.parseInt(limit, 10)));
89	    const offset = (pageNum - 1) * limitNum;
90	
91	    try {
92	      const conditions = [
93	        eq(estimates.locationId, locationId),
94	        isNull(estimates.archivedAt),
95	      ];
96	
97	      if (status && status !== 'all') {
98	        conditions.push(eq(estimates.status, status));
99	      }
100	      if (contactId && isUuid(contactId)) {
101	        conditions.push(eq(estimates.contactId, contactId));
102	      }
103	      if (dateFrom) {
104	        conditions.push(sql`${estimates.issueDate} >= ${dateFrom}::date`);
105	      }
106	      if (dateTo) {
107	        conditions.push(sql`${estimates.issueDate} <= ${dateTo}::date`);
108	      }
109	      if (search) {
110	        const q = `%${search}%`;
111	        conditions.push(
112	          or(ilike(estimates.number, q), ilike(estimates.documentTitle, q))!,
113	        );
114	      }
115	
116	      const orderCol =
117	        sortBy === 'total'
118	          ? estimates.total
119	          : sortBy === 'valid_until'
120	            ? estimates.validUntil
121	            : sortBy === 'issue_date'
122	              ? estimates.issueDate
123	              : sortBy === 'number'
124	                ? estimates.number
125	                : estimates.createdAt;
126	
127	      const orderDir = sortDir === 'asc' ? asc(orderCol) : desc(orderCol);
128	
129	      const rows = await db
130	        .select({
131	          estimate: estimates,
132	          contactFirstName: crmContacts.firstName,
133	          contactLastName: crmContacts.lastName,
134	          contactEmail: crmContacts.email,
135	        })
136	        .from(estimates)
137	        .leftJoin(crmContacts, eq(estimates.contactId, crmContacts.id))
138	        .where(and(...conditions))
139	        .orderBy(orderDir)
140	        .limit(limitNum)
141	        .offset(offset);
142	
143	      const [{ count }] = await db
144	        .select({ count: sql<number>`count(*)::int` })
145	        .from(estimates)
146	        .where(and(...conditions));
147	
148	      return c.json({
149	        data: rows.map((r) => ({
150	          ...r.estimate,
151	          contact: r.contactFirstName
152	            ? {
153	                firstName: r.contactFirstName,
154	                lastName: r.contactLastName,
155	                email: r.contactEmail,
156	              }
157	            : null,
158	        })),
159	        total: count,
160	        page: pageNum,
161	        limit: limitNum,
162	      });
163	    } catch (err) {
164	      const structured = formatErrorForUser(err, {
165	        feature: 'EST',
166	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
167	      });
168	      return c.json(
169	        {
170	          error: structured.message,
171	          reference_id: structured.reference_id,
172	          retry_safe: structured.retry_safe,
173	        },
174	        500,
175	      );
176	    }
177	  },
178	);
179	
180	// ─────────────────────────────────────────────────────────────────────────────
181	// GET /locations/:locationId/estimates/metrics
182	// ─────────────────────────────────────────────────────────────────────────────
183	
184	estimatesRouter.get(
185	  '/locations/:locationId/estimates/metrics',
186	  requireAuth(),
187	  async (c) => {
188	    const { locationId } = c.req.param();
189	    if (!isUuid(locationId))
190	      return c.json({ error: 'Invalid location ID' }, 400);
191	
192	    const authUser = c.get('authUser') as AuthUser;
193	    const location = await verifyLocationAccess(locationId, authUser);
194	    if (!location)
195	      return c.json({ error: 'Location not found or access denied' }, 403);
196	
197	    try {
198	      const rows = await db
199	        .select({ status: estimates.status, total: estimates.total })
200	        .from(estimates)
201	        .where(
202	          and(
203	            eq(estimates.locationId, locationId),
204	            isNull(estimates.archivedAt),
205	          ),
206	        );
207	
208	      let drafts = 0;
209	      let sent = 0;
210	      let accepted = 0;
211	      let declined = 0;
212	      let expired = 0;
213	      let totalSent = 0;
214	      let totalAccepted = 0;
215	
216	      const now = new Date();
217	
218	      for (const r of rows) {
219	        switch (r.status) {
220	          case 'draft':
221	            drafts++;
222	            break;
223	          case 'sent':
224	          case 'viewed':
225	            sent++;
226	            totalSent++;
227	            break;
228	          case 'accepted':
229	            accepted++;
230	            totalSent++;
231	            totalAccepted++;
232	            break;
233	          case 'declined':
234	            declined++;
235	            totalSent++;
236	            break;
237	          case 'expired':
238	            expired++;
239	            totalSent++;
240	            break;
241	        }
242	      }
243	
244	      const winRate =
245	        totalSent > 0 ? Math.round((totalAccepted / totalSent) * 100) : 0;
246	
247	      // Expiring soon — sent/viewed with valid_until within 7 days
248	      const [{ expiringSoon }] = await db
249	        .select({ expiringSoon: sql<number>`count(*)::int` })
250	        .from(estimates)
251	        .where(
252	          and(
253	            eq(estimates.locationId, locationId),
254	            isNull(estimates.archivedAt),
255	            or(eq(estimates.status, 'sent'), eq(estimates.status, 'viewed'))!,
256	            lt(estimates.validUntil, sql`(now() + interval '7 days')::date`),
257	          ),
258	        );
259	
260	      return c.json({
261	        drafts,
262	        sent,
263	        accepted,
264	        declined,
265	        expired,
266	        winRate,
267	        expiringSoon,
268	      });
269	    } catch (err) {
270	      const structured = formatErrorForUser(err, {
271	        feature: 'EST',
272	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
273	      });
274	      return c.json(
275	        {
276	          error: structured.message,
277	          reference_id: structured.reference_id,
278	          retry_safe: structured.retry_safe,
279	        },
280	        500,
281	      );
282	    }
283	  },
284	);
285	
286	// ─────────────────────────────────────────────────────────────────────────────
287	// GET /locations/:locationId/estimates/:id
288	// ─────────────────────────────────────────────────────────────────────────────
289	
290	estimatesRouter.get(
291	  '/locations/:locationId/estimates/:id',
292	  requireAuth(),
293	  async (c) => {
294	    const { locationId, id } = c.req.param();
295	    if (!isUuid(locationId) || !isUuid(id))
296	      return c.json({ error: 'Invalid ID' }, 400);
297	
298	    const authUser = c.get('authUser') as AuthUser;
299	    const location = await verifyLocationAccess(locationId, authUser);
300	    if (!location)
301	      return c.json({ error: 'Location not found or access denied' }, 403);
302	
303	    try {
304	      const [estimate] = await db
305	        .select()
306	        .from(estimates)
307	        .where(and(eq(estimates.id, id), eq(estimates.locationId, locationId)))
308	        .limit(1);
309	
310	      if (!estimate) return c.json({ error: 'Estimate not found' }, 404);
311	
312	      const [lineItems, fees, events] = await Promise.all([
313	        db
314	          .select()
315	          .from(estimateLineItems)
316	          .where(eq(estimateLineItems.estimateId, id))
317	          .orderBy(asc(estimateLineItems.position)),
318	        db
319	          .select()
320	          .from(estimateFees)
321	          .where(eq(estimateFees.estimateId, id))
322	          .orderBy(asc(estimateFees.position)),
323	        db
324	          .select()
325	          .from(estimateEvents)
326	          .where(eq(estimateEvents.estimateId, id))
327	          .orderBy(desc(estimateEvents.createdAt))
328	          .limit(50),
329	      ]);
330	
331	      return c.json({ ...estimate, lineItems, fees, events });
332	    } catch (err) {
333	      const structured = formatErrorForUser(err, {
334	        feature: 'EST',
335	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
336	      });
337	      return c.json(
338	        {
339	          error: structured.message,
340	          reference_id: structured.reference_id,
341	          retry_safe: structured.retry_safe,
342	        },
343	        500,
344	      );
345	    }
346	  },
347	);
348	
349	// ─────────────────────────────────────────────────────────────────────────────
350	// POST /locations/:locationId/estimates — create draft
351	// ─────────────────────────────────────────────────────────────────────────────
352	
353	estimatesRouter.post(
354	  '/locations/:locationId/estimates',
355	  requireAuth(),
356	  async (c) => {
357	    const { locationId } = c.req.param();
358	    if (!isUuid(locationId))
359	      return c.json({ error: 'Invalid location ID' }, 400);
360	
361	    const authUser = c.get('authUser') as AuthUser;
362	    const location = await verifyLocationAccess(locationId, authUser);
363	    if (!location)
364	      return c.json({ error: 'Location not found or access denied' }, 403);
365	
366	    let body: Record<string, unknown>;
367	    try {
368	      body = await c.req.json();
369	    } catch {
370	      return c.json({ error: 'Invalid JSON body' }, 400);
371	    }
372	
373	    const {
374	      contactId,
375	      templateId,
376	      documentTitle,
377	      issueDate,
378	      validUntil,
379	      notes,
380	      terms,
381	      footerMessage,
382	      requireSignature,
383	      allowComments,
384	      autoConvertToInvoice,
385	      discountType,
386	      discountAmount,
387	      discountCode,
388	      taxRate,
389	      taxInclusive,
390	      internalNote,
391	      source,
392	      lineItems: lineItemsInput,
393	      fees: feesInput,
394	    } = body as {
395	      contactId?: string;
396	      templateId?: string;
397	      documentTitle?: string;
398	      issueDate?: string;
399	      validUntil?: string;
400	      notes?: string;
401	      terms?: string;
402	      footerMessage?: string;
403	      requireSignature?: boolean;
404	      allowComments?: boolean;
405	      autoConvertToInvoice?: boolean;
406	      discountType?: string;
407	      discountAmount?: number;
408	      discountCode?: string;
409	      taxRate?: number;
410	      taxInclusive?: boolean;
411	      internalNote?: string;
412	      source?: string;
413	      lineItems?: Array<{
414	        productId?: string;
415	        name: string;
416	        description?: string;
417	        quantity: number;
418	        unit?: string;
419	        rate: number;
420	        amount: number;
421	        position?: number;
422	      }>;
423	      fees?: Array<{
424	        label: string;
425	        feeType: string;
426	        amount: number;
427	        appliesTo: string;
428	        position?: number;
429	      }>;
430	    };
431	
432	    if (!validUntil) return c.json({ error: 'validUntil is required' }, 400);
433	
434	    try {
435	      const number = await allocateEstimateNumber(locationId);
436	
437	      const li = Array.isArray(lineItemsInput) ? lineItemsInput : [];
438	      const fe = Array.isArray(feesInput) ? feesInput : [];
439	
440	      // Compute totals
441	      const subtotal = li.reduce((s, item) => s + Number(item.amount ?? 0), 0);
442	      let discAmt = 0;
443	      if (discountType === 'percent' && discountAmount) {
444	        discAmt = subtotal * (Number(discountAmount) / 100);
445	      } else if (discountType === 'flat' && discountAmount) {
446	        discAmt = Number(discountAmount);
447	      }
448	      const afterDiscount = subtotal - discAmt;
449	      const feesTotal = fe.reduce((s, f) => {
450	        if (f.feeType === 'percent' && f.appliesTo === 'subtotal') {
451	          return s + afterDiscount * (Number(f.amount) / 100);
452	        }
453	        return s + Number(f.amount ?? 0);
454	      }, 0);
455	      let taxTotal = 0;
456	      if (taxRate) {
457	        const taxBase = taxInclusive ? 0 : afterDiscount + feesTotal;
458	        taxTotal = taxBase * (Number(taxRate) / 100);
459	      }
460	      const total = afterDiscount + feesTotal + taxTotal;
461	
462	      const [estimate] = await db
463	        .insert(estimates)
464	        .values({
465	          flightSchoolId: location.flightSchoolId,
466	          locationId,
467	          number,
468	          status: 'draft',
469	          contactId: contactId && isUuid(contactId) ? contactId : null,
470	          templateId: templateId && isUuid(templateId) ? templateId : null,
471	          documentTitle: documentTitle ?? null,
472	          issueDate: issueDate ?? new Date().toISOString().split('T')[0],
473	          validUntil,
474	          subtotal: String(subtotal),
475	          discountType: discountType ?? null,
476	          discountAmount:
477	            discountAmount != null ? String(discountAmount) : null,
478	          discountCode: discountCode ?? null,
479	          taxRate: taxRate != null ? String(taxRate) : null,
480	          taxInclusive: taxInclusive ?? false,
481	          taxTotal: String(taxTotal),
482	          feesTotal: String(feesTotal),
483	          total: String(total),
484	          notes: notes ?? null,
485	          terms: terms ?? null,
486	          footerMessage: footerMessage ?? null,
487	          requireSignature: requireSignature ?? false,
488	          allowComments: allowComments ?? true,
489	          autoConvertToInvoice: autoConvertToInvoice ?? false,
490	          ownerId: authUser.id && isUuid(authUser.id) ? authUser.id : null,
491	          internalNote: internalNote ?? null,
492	          source: source ?? null,
493	          createdBy: authUser.id && isUuid(authUser.id) ? authUser.id : null,
494	        })
495	        .returning();
496	
497	      if (li.length > 0) {
498	        await db.insert(estimateLineItems).values(
499	          li.map((item, idx) => ({
500	            estimateId: estimate.id,
501	            productId:
502	              item.productId && isUuid(item.productId) ? item.productId : null,
503	            name: item.name,
504	            description: item.description ?? null,
505	            quantity: String(item.quantity),
506	            unit: item.unit ?? null,
507	            rate: String(item.rate),
508	            amount: String(item.amount),
509	            position: item.position ?? idx,
510	          })),
511	        );
512	      }
513	
514	      if (fe.length > 0) {
515	        await db.insert(estimateFees).values(
516	          fe.map((f, idx) => ({
517	            estimateId: estimate.id,
518	            label: f.label,
519	            feeType: f.feeType ?? 'flat',
520	            amount: String(f.amount),
521	            appliesTo: f.appliesTo ?? 'subtotal',
522	            position: f.position ?? idx,
523	          })),
524	        );
525	      }
526	
527	      await logEvent(estimate.id, 'created', 'user', authUser.id ?? null, {
528	        number,
529	      });
530	
531	      return c.json(estimate, 201);
532	    } catch (err) {
533	      const structured = formatErrorForUser(err, {
534	        feature: 'EST',
535	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
536	      });
537	      return c.json(
538	        {
539	          error: structured.message,
540	          reference_id: structured.reference_id,
541	          retry_safe: structured.retry_safe,
542	        },
543	        500,
544	      );
545	    }
546	  },
547	);
