549	// ─────────────────────────────────────────────────────────────────────────────
550	// PATCH /locations/:locationId/estimates/:id — update fields + nested rows
551	// ─────────────────────────────────────────────────────────────────────────────
552	
553	estimatesRouter.patch(
554	  '/locations/:locationId/estimates/:id',
555	  requireAuth(),
556	  async (c) => {
557	    const { locationId, id } = c.req.param();
558	    if (!isUuid(locationId) || !isUuid(id))
559	      return c.json({ error: 'Invalid ID' }, 400);
560	
561	    const authUser = c.get('authUser') as AuthUser;
562	    const location = await verifyLocationAccess(locationId, authUser);
563	    if (!location)
564	      return c.json({ error: 'Location not found or access denied' }, 403);
565	
566	    let body: Record<string, unknown>;
567	    try {
568	      body = await c.req.json();
569	    } catch {
570	      return c.json({ error: 'Invalid JSON body' }, 400);
571	    }
572	
573	    try {
574	      const [existing] = await db
575	        .select()
576	        .from(estimates)
577	        .where(and(eq(estimates.id, id), eq(estimates.locationId, locationId)))
578	        .limit(1);
579	
580	      if (!existing) return c.json({ error: 'Estimate not found' }, 404);
581	
582	      if (['accepted', 'declined', 'converted'].includes(existing.status)) {
583	        return c.json(
584	          { error: `Cannot edit estimate in status "${existing.status}"` },
585	          409,
586	        );
587	      }
588	
589	      // Build update set — only include provided fields
590	      const updateSet: Record<string, unknown> = {
591	        updatedAt: new Date(),
592	      };
593	
594	      const strFields = [
595	        'contactId',
596	        'templateId',
597	        'documentTitle',
598	        'validUntil',
599	        'issueDate',
600	        'notes',
601	        'terms',
602	        'footerMessage',
603	        'discountType',
604	        'discountCode',
605	        'internalNote',
606	        'source',
607	      ] as const;
608	
609	      for (const f of strFields) {
610	        if (f in body) updateSet[f] = body[f] as string | null;
611	      }
612	
613	      const numFields = ['discountAmount', 'taxRate'] as const;
614	      for (const f of numFields) {
615	        if (f in body)
616	          updateSet[f] = body[f] != null ? String(body[f] as number) : null;
617	      }
618	
619	      const boolFields = [
620	        'taxInclusive',
621	        'requireSignature',
622	        'allowComments',
623	        'autoConvertToInvoice',
624	      ] as const;
625	      for (const f of boolFields) {
626	        if (f in body) updateSet[f] = body[f] as boolean;
627	      }
628	
629	      // Recompute totals if line items or fees provided
630	      const li = Array.isArray(body.lineItems)
631	        ? (body.lineItems as Array<{
632	            id?: string;
633	            productId?: string;
634	            name: string;
635	            description?: string;
636	            quantity: number;
637	            unit?: string;
638	            rate: number;
639	            amount: number;
640	            position?: number;
641	          }>)
642	        : null;
643	
644	      const fe = Array.isArray(body.fees)
645	        ? (body.fees as Array<{
646	            id?: string;
647	            label: string;
648	            feeType: string;
649	            amount: number;
650	            appliesTo: string;
651	            position?: number;
652	          }>)
653	        : null;
654	
655	      if (li !== null || fe !== null) {
656	        const activeLi = li ?? [];
657	        const activeFe = fe ?? [];
658	        const subtotal = activeLi.reduce(
659	          (s, item) => s + Number(item.amount ?? 0),
660	          0,
661	        );
662	        const discType =
663	          (updateSet.discountType as string) ?? existing.discountType;
664	        const discAmt =
665	          (updateSet.discountAmount as string) != null
666	            ? Number(updateSet.discountAmount)
667	            : Number(existing.discountAmount ?? 0);
668	        let discountedAmt = subtotal;
669	        if (discType === 'percent') discountedAmt -= subtotal * (discAmt / 100);
670	        else if (discType === 'flat') discountedAmt -= discAmt;
671	
672	        const feesTotal = activeFe.reduce((s, f) => {
673	          if (f.feeType === 'percent' && f.appliesTo === 'subtotal')
674	            return s + discountedAmt * (Number(f.amount) / 100);
675	          return s + Number(f.amount ?? 0);
676	        }, 0);
677	
678	        const taxRateVal =
679	          (updateSet.taxRate as string) != null
680	            ? Number(updateSet.taxRate)
681	            : Number(existing.taxRate ?? 0);
682	        const taxInclusive =
683	          (updateSet.taxInclusive as boolean) ?? existing.taxInclusive;
684	        let taxTotal = 0;
685	        if (taxRateVal && !taxInclusive) {
686	          taxTotal = (discountedAmt + feesTotal) * (taxRateVal / 100);
687	        }
688	        updateSet.subtotal = String(subtotal);
689	        updateSet.feesTotal = String(feesTotal);
690	        updateSet.taxTotal = String(taxTotal);
691	        updateSet.total = String(discountedAmt + feesTotal + taxTotal);
692	      }
693	
694	      const [updated] = await db
695	        .update(estimates)
