188	// POST /tc/accept — Accept the current T&C on behalf of the school
189	// Only school admins can accept.
190	// ═══════════════════════════════════════════════════════════════════════════
191	tc.post('/tc/accept', requireAdmin(), async (c) => {
192	  try {
193	    const authUser = c.get('authUser') as AuthUser;
194	    const orgId = await resolveOrgIdFromSession(authUser, c);
195	
196	    // Get current active version
197	    const [currentVersion] = await db
198	      .select()
199	      .from(schema.tcVersions)
200	      .where(eq(schema.tcVersions.isActive, true))
201	      .orderBy(desc(schema.tcVersions.publishedAt))
202	      .limit(1);
203	
204	    if (!currentVersion) {
205	      return c.json({ error: 'No active T&C version found' }, 404);
206	    }
207	
208	    // Resolve the app user ID
209	    const appUserId = await tcRepository.findUserIdByEmail(authUser.email);
210	    if (!appUserId) {
211	      return c.json({ error: 'Could not resolve user ID' }, 400);
212	    }
213	
214	    // Scope the acceptance: prefer the session-resolved org (covers super_admin
215	    // acting on a managed school), falling back to the accepting user's own
216	    // flight school so the record is never written NULL-scoped. School-less
217	    // users (e.g. platform super_admin with no managed school) remain null.
218	    const agreementSchoolId =
219	      orgId ?? (await resolveOrgIdFromUserId(appUserId));
220	
221	    // Create the agreement record
222	    const [inserted] = await db
223	      .insert(schema.tcAgreements)
224	      .values({
225	        userId: appUserId,
226	        flightSchoolId: agreementSchoolId ?? undefined,
227	        tcVersionId: currentVersion.id,
228	        agreedAt: new Date(),
229	      })
230	      .returning();
231	
232	    // If the school was in Pending status, activate it
233	    if (orgId) {
234	      await db
235	        .update(schema.flightSchools)
236	        .set({ status: 'Active' })
237	        .where(
238	          and(
239	            eq(schema.flightSchools.id, orgId),
240	            eq(schema.flightSchools.status, 'Pending'),
241	          ),
242	        );
243	    }
244	
245	    return c.json({
246	      accepted: true,
247	      agreement: inserted
248	        ? {
249	            id: inserted.id,
250	            userId: inserted.userId,
251	            tcVersionId: inserted.tcVersionId,
252	            agreedAt: inserted.agreedAt?.toISOString() ?? '',
253	          }
254	        : null,
255	    });
256	  } catch (err: unknown) {
257	    const structured = formatErrorForUser(err, {
258	      feature: 'TC',
259	      actor: (c.get('authUser') as AuthUser | undefined)?.id,
260	    });
261	    return c.json(
262	      {
263	        error: structured.message,
264	        reference_id: structured.reference_id,
265	        retry_safe: structured.retry_safe,
266	      },
267	      500,
268	    );
269	  }
270	});
