2346	function resolveSignerContext(
2347	  isAdminToken: boolean,
2348	  currentWorkflowStep: number,
2349	  signerWorkflow: schema.SignerWorkflow | null,
2350	): {
2351	  role: 'student' | 'admin';
2352	  stepId: string;
2353	  stepLabel: string;
2354	  stepOrder: number;
2355	  totalSteps: number;
2356	} {
2357	  const totalSteps = signerWorkflow?.steps.length ?? 1;
2358	  if (!signerWorkflow || !isAdminToken) {
2359	    // Student step or no workflow configured
2360	    const step = signerWorkflow?.steps[0];
2361	    return {
2362	      role: 'student',
2363	      stepId: step?.id ?? 'student',
2364	      stepLabel: step?.label ?? 'Student',
2365	      stepOrder: 1,
2366	      totalSteps,
2367	    };
2368	  }
2369	  const step = signerWorkflow.steps.find(
2370	    (s) => s.order === currentWorkflowStep,
2371	  );
2372	  if (!step) {
2373	    return {
2374	      role: 'admin',
2375	      stepId: 'admin',
2376	      stepLabel: 'Administrator',
2377	      stepOrder: currentWorkflowStep,
2378	      totalSteps,
2379	    };
2380	  }
2381	  return {
2382	    role: step.role,
2383	    stepId: step.id,
2384	    stepLabel: step.label,
2385	    stepOrder: step.order,
2386	    totalSteps,
2387	  };
2388	}
