2952	// ─── Helper: generate signed PDF using pdf-lib ────────────────────────────────
2953	
2954	async function generateAndUploadSignedPdf(opts: {
2955	  agreement: typeof schema.studentAgreements.$inferSelect;
2956	  fieldDefinitions: schema.FieldDefinition[];
2957	  fieldValues: Record<string, string | boolean>;
2958	  signerName: string;
2959	  ip: string;
2960	  signedAt: Date;
2961	  allSigningSteps?: schema.StepSigningRecord[];
2962	}): Promise<{ url: string; key: string }> {
2963	  const {
2964	    agreement,
2965	    fieldDefinitions,
2966	    fieldValues,
2967	    signerName,
2968	    ip,
2969	    signedAt,
2970	    allSigningSteps,
2971	  } = opts;
2972	
2973	  // Fetch original PDF bytes from S3
2974	  const getCmd = new GetObjectCommand({
2975	    Bucket: BUCKET,
2976	    Key: agreement.storagePath,
2977	  });
2978	  const s3Response = await s3.send(getCmd);
2979	  if (!s3Response.Body) throw new Error('Empty S3 response');
2980	
2981	  // Convert S3 readable stream to Buffer
2982	  const chunks: Uint8Array[] = [];
2983	  for await (const chunk of s3Response.Body as AsyncIterable<Uint8Array>) {
2984	    chunks.push(chunk);
2985	  }
2986	  const pdfBytes = Buffer.concat(chunks);
2987	
2988	  // Load PDF with pdf-lib
2989	  const pdfDoc = await PDFDocument.load(pdfBytes);
2990	  // Embed Helvetica explicitly so we can use font metrics (heightAtSize)
2991	  // for accurate vertical centering and so all stamped text uses the same
2992	  // font without relying on pdf-lib's default-font auto-embedding.
2993	  const helvetica = await pdfDoc.embedFont(StandardFonts.Helvetica);
2994	  const pages = pdfDoc.getPages();
2995	
2996	  // Stamp each field value onto the correct page
2997	  for (const field of fieldDefinitions) {
2998	    const pageIndex = (field.page ?? 1) - 1;
2999	    const page = pages[pageIndex];
3000	    if (!page) continue;
3001	
3002	    const { width: pageWidth, height: pageHeight } = page.getSize();
3003	    const box = computeFieldBox({
3004	      xPct: field.x,
3005	      yPct: field.y,
3006	      widthPx: field.width ?? 100,
3007	      heightPx: field.height ?? 20,
3008	      pageWidthPt: pageWidth,
3009	      pageHeightPt: pageHeight,
3010	    });
3011	
3012	    const value = fieldValues[field.id];
3013	
3014	    if (field.type === 'signature' || field.type === 'initials') {
3015	      // Value is a data URL (image/png)
3016	      if (typeof value === 'string' && value.startsWith('data:image/')) {
3017	        try {
3018	          const base64 = value.split(',')[1];
3019	          if (base64) {
3020	            const imgBytes = Buffer.from(base64, 'base64');
3021	            const img = await pdfDoc.embedPng(imgBytes);
3022	            page.drawImage(img, {
3023	              x: box.x,
3024	              y: box.y,
3025	              width: box.widthPt,
3026	              height: box.heightPt,
3027	            });
3028	          }
3029	        } catch {
3030	          // Skip if image embedding fails
3031	        }
3032	      }
3033	    } else if (field.type === 'checkbox') {
3034	      if (value === true) {
3035	        const size = Math.min(box.heightPt - 2, 11);
3036	        // Use 'X' rather than U+2713 — Helvetica's WinAnsi encoding does not
3037	        // include the unicode checkmark glyph and would throw at draw time.
3038	        page.drawText('X', {
3039	          x: box.x + 2,
3040	          y: box.y + (box.heightPt - size) / 2,
3041	          size,
3042	          font: helvetica,
3043	          color: rgb(0, 0.5, 0.3),
3044	        });
3045	      }
3046	    } else {
3047	      // Text field: auto-fill or manual input
3048	      const displayValue = typeof value === 'string' ? value : '';
3049	      if (displayValue) {
3050	        const fontSize = Math.min(box.heightPt * 0.7, 11);
3051	        const ascentPt = helvetica.heightAtSize(fontSize, { descender: false });
3052	        const totalHeight = helvetica.heightAtSize(fontSize);
3053	        const descentPt = totalHeight - ascentPt;
3054	        const baselineY = centerBaselineY({
3055	          boxBottomY: box.y,
3056	          boxHeightPt: box.heightPt,
3057	          ascentPt,
3058	          descentPt,
3059	        });
3060	        page.drawText(displayValue, {
3061	          x: box.x + 2,
3062	          y: baselineY,
3063	          size: fontSize,
3064	          font: helvetica,
3065	          color: rgb(0.1, 0.1, 0.1),
3066	          maxWidth: box.widthPt - 4,
3067	        });
3068	      }
3069	    }
3070	  }
3071	
3072	  // Add audit trail page
3073	  const auditPage = pdfDoc.addPage();
3074	  const { height: auditHeight } = auditPage.getSize();
3075	  const auditLines: string[] = [
3076	    'Electronic Signature Audit Trail',
3077	    '',
3078	    `Document: ${agreement.name}`,
3079	    `Document ID: ${agreement.id}`,
3080	    '',
3081	  ];
3082	
3083	  if (allSigningSteps && allSigningSteps.length > 1) {
3084	    // Multi-party audit trail — list each signer
3085	    for (const step of allSigningSteps) {
3086	      auditLines.push(
3087	        `Signer (Step ${step.order}): ${step.signerName ?? 'Unknown'}`,
3088	        `  Signed on: ${step.signedAt ?? 'n/a'}`,
3089	        `  IP Address: ${step.signerIpAddress ?? 'n/a'}`,
3090	        '',
3091	      );
3092	    }
3093	  } else {
3094	    // Single-party audit trail
3095	    auditLines.push(
3096	      `Signed by: ${signerName}`,
3097	      `Signed on: ${signedAt.toISOString()}`,
3098	      `IP Address: ${ip}`,
3099	      `Token: ${agreement.signingToken ?? 'n/a'}`,
3100	      '',
3101	    );
3102	  }
3103	  auditLines.push(
3104	    'This document was signed electronically using HILO Aviation platform.',
3105	  );
3106	
3107	  let lineY = auditHeight - 60;
3108	  for (const line of auditLines) {
3109	    auditPage.drawText(line, {
3110	      x: 50,
3111	      y: lineY,
3112	      size: line === 'Electronic Signature Audit Trail' ? 14 : 10,
3113	      color: rgb(0.1, 0.1, 0.1),
3114	    });
3115	    lineY -= line === 'Electronic Signature Audit Trail' ? 24 : 16;
3116	  }
3117	
3118	  // Save modified PDF
3119	  const signedPdfBytes = await pdfDoc.save();
3120	
3121	  // Upload to S3 under signed/ prefix
3122	  const signedKey = getSignedAgreementKey({
3123	    id: agreement.id,
3124	    flightSchoolId: agreement.flightSchoolId,
3125	  });
3126	  await s3.send(
3127	    new PutObjectCommand({
3128	      Bucket: BUCKET,
3129	      Key: signedKey,
3130	      Body: Buffer.from(signedPdfBytes),
3131	      ContentType: 'application/pdf',
3132	    }),
3133	  );
3134	
3135	  // Return both the persisted key (source of truth — survives indefinitely)
3136	  // and a transitional 24-hour presigned URL the post-signing email embeds for
3137	  // immediate-use clicks. The drawer/UI no longer rely on the URL — they call
3138	  // GET /agreements/:id/signed-url to mint a fresh URL on every click. See
3139	  // ticket 1214588596513434 for the full root-cause writeup.
3140	  const url = await getSignedUrl(
3141	    s3,
3142	    new GetObjectCommand({ Bucket: BUCKET, Key: signedKey }),
3143	    { expiresIn: 86400 },
3144	  );
3145	  return { url, key: signedKey };
3146	}
