273	export function getInitials(name: string): string {
274	  const parts = name.trim().split(/\s+/);
275	  if (parts.length === 1) return (parts[0]?.charAt(0) ?? '').toUpperCase();
276	  return (
277	    (parts[0]?.charAt(0) ?? '') + (parts[parts.length - 1]?.charAt(0) ?? '')
278	  )
279	    .toUpperCase()
280	    .slice(0, 4);
281	}
