283	function renderTypedSignature(
284	  text: string,
285	  isInitials: boolean,
286	  fontFamily: string,
287	  inkHex: string,
288	  targetWidth?: number,
289	  targetHeight?: number,
290	): string {
291	  // Use 2× field dimensions for retina; fall back to a default 3:1 canvas
292	  const canvasWidth = targetWidth ? targetWidth * 2 : 300;
293	  const canvasHeight = targetHeight ? targetHeight * 2 : 100;
294	  const canvas = document.createElement('canvas');
295	  canvas.width = canvasWidth;
296	  canvas.height = canvasHeight;
297	  const ctx = canvas.getContext('2d');
298	  if (!ctx) return '';
299	  ctx.fillStyle = '#ffffff';
300	  ctx.fillRect(0, 0, canvasWidth, canvasHeight);
301	  ctx.fillStyle = inkHex;
302	  const displayText = isInitials ? getInitials(text) : text;
303	  // Target 72% of canvas height; scale down if text would overflow width
304	  let fontSize = Math.floor(canvasHeight * 0.72);
305	  ctx.font = `${fontSize}px ${fontFamily}`;
306	  const maxTextWidth = canvasWidth - 8;
307	  const measured = ctx.measureText(displayText);
308	  if (measured.width > maxTextWidth) {
309	    fontSize = Math.floor(fontSize * (maxTextWidth / measured.width));
310	    ctx.font = `${fontSize}px ${fontFamily}`;
311	  }
312	  ctx.textAlign = 'center';
313	  ctx.textBaseline = 'middle';
314	  ctx.fillText(displayText, canvasWidth / 2, canvasHeight / 2);
315	  return canvas.toDataURL('image/png');
316	}
