332	  pageWidth,
333	  pageHeight,
334	  value,
335	  onChange,
336	  onSignatureClick,
337	  readOnly,
338	}: FieldOverlayProps) {
339	  const left = (field.x / 100) * pageWidth;
340	  const top = (field.y / 100) * pageHeight;
341	
342	  const isAutoFill = Boolean(field.autoFillValue);
343	
344	  const style = {
345	    position: 'absolute' as const,
346	    left: `${left}px`,
347	    top: `${top}px`,
348	    width: `${field.width}px`,
349	    height: `${field.height}px`,
350	  };
351	
352	  if (field.type === 'checkbox') {
353	    return (
354	      <div style={style} className="flex items-center justify-center">
355	        <input
356	          type="checkbox"
357	          checked={Boolean(value)}
358	          onChange={readOnly ? undefined : (e) => onChange(e.target.checked)}
359	          readOnly={readOnly}
360	          disabled={readOnly}
361	          className={`w-5 h-5 ${readOnly ? 'cursor-default opacity-70' : 'accent-teal-500 cursor-pointer'}`}
362	        />
363	      </div>
364	    );
365	  }
366	
367	  if (field.type === 'signature' || field.type === 'initials') {
368	    const hasSig = typeof value === 'string' && value.startsWith('data:');
369	    if (readOnly) {
370	      return (
371	        <div
372	          style={style}
373	          className="rounded border border-slate-300 bg-transparent flex items-center justify-center"
374	        >
375	          {hasSig && (
376	            <img
377	              src={value as string}
378	              alt="Signature"
379	              className="w-full h-full object-contain"
380	            />
381	          )}
382	        </div>
383	      );
384	    }
385	    return (
386	      <div
387	        style={style}
388	        className={`rounded flex items-center justify-center cursor-pointer transition-colors ${hasSig ? 'border border-slate-300 bg-transparent' : 'border-2 border-dashed border-blue-400 bg-blue-50 hover:bg-blue-100'}`}
389	        onClick={() => onSignatureClick(field.id)}
390	      >
391	        {hasSig ? (
392	          <img
393	            src={value as string}
394	            alt="Signature"
395	            className="w-full h-full object-contain"
396	          />
397	        ) : (
398	          <span className="text-xs text-blue-600 font-medium">
399	            {field.type === 'initials' ? 'Initials here' : 'Click to sign'}
400	          </span>
401	        )}
402	      </div>
403	    );
404	  }
405	
406	  // Text-based auto-fill field — use the live value prop so inline chips reflect
407	  // what the user typed in the right panel, not a stale label from resolveAutoFill.
408	  if (isAutoFill) {
409	    const displayText =
410	      typeof value === 'string' && value.trim()
411	        ? value
412	        : resolveAutoFill(field.autoFillValue ?? '');
413	    const hasFilled = typeof value === 'string' && value.trim().length > 0;
414	
415	    if (hasFilled) {
416	      // Filled: plain document text — no chip chrome, no signature font, no tint.
417	      // Use the field's own height to derive a readable font-size that fits within
418	      // the bounding box without overflowing; align to bottom so text sits on the
419	      // PDF underline rather than floating above it.
420	      return (
421	        <div style={style} className="overflow-hidden flex items-end pb-px">
422	          <span
423	            className="truncate"
424	            style={{
425	              fontSize: `${Math.min(field.height * 0.62, 14)}px`,
426	              lineHeight: 1.2,
427	              color: 'inherit',
428	            }}
429	          >
430	            {displayText}
431	          </span>
432	        </div>
433	      );
434	    }
