205	/**
206	 * Fetches a fresh short-lived signed URL for a signed agreement PDF and either
207	 * opens it in a new tab (view) or triggers a download. Replaces the previous
208	 * pattern of binding `<a href={agreement.signedPdfUrl}>` straight to the 24h
209	 * presigned URL stored at signing time, which expired silently and surfaced as
210	 * raw S3 AccessDenied XML to users (ticket 1214588596513434).
211	 *
212	 * Errors surface a Hilo-styled toast — no raw XML page, no silent empty state.
213	 */
214	async function openSignedAgreement(
215	  agreement: { id: string; name: string; fileName: string },
216	  disposition: 'inline' | 'attachment',
217	): Promise<void> {
218	  try {
219	    const res = await fetch(
220	      `${API_BASE}/agreements/${encodeURIComponent(agreement.id)}/signed-url?disposition=${disposition}`,
221	      {
222	        method: 'GET',
223	        headers: getServerApiHeaders(),
224	        credentials: 'include',
225	      },
226	    );
227	
228	    if (!res.ok) {
229	      const errPayload = (await res.json().catch(() => ({}))) as {
230	        error?: string;
231	      };
232	      const fallback =
233	        res.status === 403
234	          ? 'You do not have access to this signed agreement.'
235	          : res.status === 404
236	            ? 'Signed document is no longer available — contact support.'
237	            : 'Could not open the signed agreement. Please try again.';
238	      toast.error(errPayload.error ?? fallback);
239	      return;
240	    }
241	
242	    const { url } = (await res.json()) as { url: string; expiresAt: string };
243	    if (!url) {
244	      toast.error('Could not open the signed agreement. Please try again.');
245	      return;
246	    }
247	
248	    if (disposition === 'attachment') {
249	      const a = document.createElement('a');
250	      a.href = url;
251	      a.download = agreement.fileName ?? `${agreement.name}.pdf`;
252	      a.rel = 'noopener noreferrer';
253	      document.body.appendChild(a);
254	      a.click();
255	      document.body.removeChild(a);
256	    } else {
257	      window.open(url, '_blank', 'noopener,noreferrer');
258	    }
259	  } catch (err) {
260	    const msg =
261	      err instanceof Error
262	        ? err.message
263	        : typeof err === 'object' && err !== null
264	          ? JSON.stringify(err)
265	          : String(err);
266	    console.error('[student-agreements] signed URL fetch failed:', msg);
267	    toast.error('Could not open the signed agreement. Please try again.');
268	  }
269	}
