153	function formatCurrency(val: number | string) {
154	  return new Intl.NumberFormat('en-US', {
155	    style: 'currency',
156	    currency: 'USD',
157	    minimumFractionDigits: 2,
158	  }).format(Number(val));
159	}
160	
161	function formatDate(dateStr: string) {
162	  if (!dateStr) return '—';
163	  try {
164	    return new Date(dateStr).toLocaleDateString('en-US', {
165	      month: 'short',
166	      day: 'numeric',
167	      year: 'numeric',
168	    });
169	  } catch {
170	    return dateStr;
171	  }
172	}
173	
174	function getInitials(name: string) {
175	  const parts = name.trim().split(/\s+/);
176	  return parts.length >= 2
177	    ? `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase()
178	    : name.substring(0, 2).toUpperCase();
179	}
180	
181	function contactDisplayName(
182	  contact: Estimate['contact'] | undefined | null,
183	): string {
184	  if (!contact) return '—';
185	  return [contact.firstName, contact.lastName].filter(Boolean).join(' ') || '—';
186	}
