80	function timeAgo(dateStr: string) {
81	  const diff = Date.now() - new Date(dateStr).getTime();
82	  const mins = Math.floor(diff / 60000);
83	  if (mins < 1) return 'Just now';
84	  if (mins < 60) return `${mins}m`;
85	  const hrs = Math.floor(mins / 60);
86	  if (hrs < 24) return `${hrs}h`;
87	  const days = Math.floor(hrs / 24);
88	  return `${days}d`;
89	}
